#include <stdint.h>
#include <string.h>

#define HLS_BLOCK_SIZE 16

void crypto_kernel(const uint8_t plaintext[HLS_BLOCK_SIZE],
                    const uint8_t key[HLS_BLOCK_SIZE],
                    uint8_t ciphertext[HLS_BLOCK_SIZE],
                    int *status_out,
                    unsigned int *iter_count_out)
{
    int checksum = 0;

    for (int i = 0; i < HLS_BLOCK_SIZE; i++) {
        ciphertext[i] = (uint8_t)(plaintext[i] ^ key[i]);
        checksum ^= plaintext[i];
    }

    if (key[0] == 0) {
        *status_out = 1;
    } else {
        *status_out = checksum;
    }
    *iter_count_out = HLS_BLOCK_SIZE;
}

#include <stdint.h>
#include <string.h>

#define HLS_BLOCK_SIZE 16

void crypto_kernel(const uint8_t plaintext[HLS_BLOCK_SIZE],
                    const uint8_t key[HLS_BLOCK_SIZE],
                    uint8_t ciphertext[HLS_BLOCK_SIZE],
                    int *status_out,
                    unsigned int *iter_count_out)
{
    int checksum = 0;
    for (int i = 0; i < HLS_BLOCK_SIZE; i++) {
        checksum ^= plaintext[i];
    }

    if (key[0] == 0) {
        /* Secret-dependent early exit: skips the XOR loop entirely and
         * reports a different iteration count, leaking key[0]==0 via
         * iter_count_out. */
        memset(ciphertext, 0, HLS_BLOCK_SIZE);
        *status_out = checksum;
        *iter_count_out = 0;
        return;
    }

    for (int i = 0; i < HLS_BLOCK_SIZE; i++) {
        ciphertext[i] = (uint8_t)(plaintext[i] ^ key[i]);
    }

    *status_out = checksum;
    *iter_count_out = HLS_BLOCK_SIZE;
}

