                    const uint8_t key[HLS_BLOCK_SIZE],
                    uint8_t ciphertext[HLS_BLOCK_SIZE],
                    int *status_out,
                    unsigned int *iter_count_out)
{
    int checksum = 0;

    for (int i = 0; i < HLS_BLOCK_SIZE; i++) {
        ciphertext[i] = (uint8_t)(plaintext[i] ^ key[i]);
        checksum ^= plaintext[i];
    }

    *status_out = checksum;
    *iter_count_out = HLS_BLOCK_SIZE;

    /* Diagnostic override: forces a fixed 'stuck-at' sentinel value on the
     * public status/iteration outputs whenever a secret-dependent
     * condition holds, reintroducing a key-dependent observable
     * discrepancy that differs between runs with different keys sharing
     * the same plaintext. */
    if (key[0] == 0) {
        *status_out = -1;
        *iter_count_out = 0;
    }
}

